package com.zhuqiyun.procurement;

import com.zhuqiyun.platform.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import static com.zhuqiyun.domain.Rules.*;

@Service
public class ProcurementService {
 private final Db db; private final Auth auth;
 public ProcurementService(Db db,Auth auth){this.db=db;this.auth=auth;}
 private Map<String,Object> request(long id,boolean lock){Map<String,Object> r=db.one("SELECT * FROM purchase_requests WHERE tenant_id=1 AND id=?"+(lock?" FOR UPDATE":""),id);auth.project(((Number)r.get("project_id")).longValue());return r;}
 private Map<String,Object> order(long id,boolean lock){Map<String,Object> r=db.one("SELECT * FROM purchase_orders WHERE tenant_id=1 AND id=?"+(lock?" FOR UPDATE":""),id);auth.project(((Number)r.get("project_id")).longValue());return r;}
 public List<Map<String,Object>> requests(){auth.require("request:read");List<Map<String,Object>> rows=db.list("SELECT r.*,p.name project_name,u.name applicant_name FROM purchase_requests r JOIN projects p ON p.id=r.project_id JOIN users u ON u.id=r.applicant_id WHERE "+auth.projectFilter("p")+" ORDER BY r.id DESC");for(Map<String,Object> r:rows)r.put("items",requestItems(((Number)r.get("id")).longValue()));return rows;}
 public List<Map<String,Object>> requestItems(long id){return db.list("SELECT i.*,m.name material_name,m.specification,m.unit FROM request_items i JOIN materials m ON m.id=i.material_id WHERE i.request_id=? ORDER BY i.id",id);}
 public Map<String,Object> detail(long id){auth.require("request:read");Map<String,Object> r=request(id,false);r.putAll(db.one("SELECT p.name project_name,u.name applicant_name FROM purchase_requests r JOIN projects p ON p.id=r.project_id JOIN users u ON u.id=r.applicant_id WHERE r.id=?",id));r.put("items",requestItems(id));r.put("quotes",quotes(id));r.put("approvals",db.list("SELECT a.*,u.name operator_name FROM approvals a JOIN users u ON u.id=a.operator_id WHERE a.request_id=? ORDER BY a.id",id));return r;}
 @Transactional public Map<String,Object> save(Long id,Map<String,Object> input){
  auth.require("request:write");long project=id(input,"project_id");auth.project(project);Map<String,Object> p=db.one("SELECT * FROM projects WHERE id=? AND tenant_id=1",project);check(!Set.of("COMPLETED","SUSPENDED").contains(p.get("status")),"项目当前状态不可申请采购");
  Map<String,Object> r;if(id!=null){r=request(id,true);check(Set.of("DRAFT","REJECTED").contains(r.get("status")),"只有草稿或已驳回申请可编辑");check(!auth.isManager()||((Number)r.get("applicant_id")).longValue()==auth.id(),"只能修改本人申请");check(db.list("SELECT id FROM quotes WHERE request_id=?",id).isEmpty(),"已有报价的申请不可修改");}
  LocalDate required=date(input,"required_date");check(!required.isBefore(LocalDate.now()),"需求日期不可早于今天");
  List<Map<String,Object>> lines=new ArrayList<>();Set<Long> seen=new HashSet<>();BigDecimal total=BigDecimal.ZERO;
  for(Map<String,Object> line:items(input)){long material=id(line,"material_id");unique(seen,material);db.one("SELECT id FROM materials WHERE id=? AND tenant_id=1",material);BigDecimal qty=decimal(line,"quantity",3,true),price=decimal(line,"unit_price",4,true),amount=money(qty.multiply(price));total=total.add(amount);lines.add(row("material_id",material,"quantity",qty,"unit_price",price,"amount",amount));}
  Map<String,Object> fields=row("project_id",project,"required_date",required,"note",optional(input,"note"),"total_amount",total,"status","DRAFT");
  if(id==null){fields.put("code",code("PR"));fields.put("applicant_id",auth.id());id=db.insert("purchase_requests",fields);}else{db.update("purchase_requests",id,fields);db.jdbc().update("DELETE FROM request_items WHERE request_id=?",id);}
  for(Map<String,Object> line:lines){line.put("request_id",id);db.insert("request_items",line);}auth.audit("SAVE_REQUEST","purchase_request",id,"预估金额 "+total);return detail(id);
 }
 @Transactional public Map<String,Object> submit(long id){auth.require("request:write");Map<String,Object> r=request(id,true);check(!auth.isManager()||((Number)r.get("applicant_id")).longValue()==auth.id(),"只能提交本人申请");check(Set.of("DRAFT","REJECTED").contains(r.get("status")),"申请当前不可提交");check(!requestItems(id).isEmpty(),"申请明细不能为空");db.update("purchase_requests",id,row("status","PENDING"));db.insert("approvals",row("request_id",id,"operator_id",auth.id(),"decision","SUBMITTED","comment","提交采购审批"));auth.audit("SUBMIT_REQUEST","purchase_request",id,"提交审批");return detail(id);}
 @Transactional public Map<String,Object> approve(long id,Map<String,Object> input){auth.require("request:approve");Map<String,Object> r=request(id,true);check("PENDING".equals(r.get("status")),"只有待审批申请可审批");check(((Number)r.get("applicant_id")).longValue()!=auth.id(),"申请人与审批人必须不同");String decision=text(input,"decision"),comment=text(input,"comment");check(Set.of("APPROVED","REJECTED").contains(decision),"审批结论无效");db.update("purchase_requests",id,row("status",decision));db.insert("approvals",row("request_id",id,"operator_id",auth.id(),"decision",decision,"comment",comment));auth.audit(decision,"purchase_request",id,comment);return detail(id);}
 public List<Map<String,Object>> quotes(long requestId){auth.require("request:read");request(requestId,false);List<Map<String,Object>> rows=db.list("SELECT q.*,s.name supplier_name,s.rating,s.qualification_expiry FROM quotes q JOIN suppliers s ON s.id=q.supplier_id WHERE q.request_id=? ORDER BY q.total_amount",requestId);for(Map<String,Object> r:rows)r.put("items",db.list("SELECT qi.*,ri.material_id,ri.quantity,m.name material_name,m.specification,m.unit FROM quote_items qi JOIN request_items ri ON ri.id=qi.request_item_id JOIN materials m ON m.id=ri.material_id WHERE qi.quote_id=? ORDER BY ri.id",r.get("id")));return rows;}
 @Transactional public Map<String,Object> quote(long requestId,Map<String,Object> input){auth.require("quote:write");Map<String,Object> r=request(requestId,true);check("APPROVED".equals(r.get("status")),"审批通过后才可询价");check(db.list("SELECT id FROM purchase_orders WHERE request_id=?",requestId).isEmpty(),"已下单不可继续报价");long supplier=id(input,"supplier_id");Map<String,Object> s=db.one("SELECT * FROM suppliers WHERE id=? AND tenant_id=1",supplier);check("ACTIVE".equals(s.get("status")),"供应商已停用");if(s.get("qualification_expiry")!=null)check(!LocalDate.parse(s.get("qualification_expiry").toString()).isBefore(LocalDate.now()),"供应商资质已过期");long days=id(input,"delivery_days");check(days<=365,"交货天数不可超过365天");LocalDate valid=date(input,"valid_until");check(!valid.isBefore(LocalDate.now()),"报价有效期已过");List<Map<String,Object>> required=requestItems(requestId);Set<Long> seen=new HashSet<>();List<Map<String,Object>> lines=new ArrayList<>();BigDecimal total=BigDecimal.ZERO;
  for(Map<String,Object> line:items(input)){long requestItem=id(line,"request_item_id");unique(seen,requestItem);Map<String,Object> ri=required.stream().filter(x->((Number)x.get("id")).longValue()==requestItem).findFirst().orElseThrow(()->new IllegalArgumentException("报价明细不属于此申请"));BigDecimal price=decimal(line,"unit_price",4,true),amount=money(dec(ri.get("quantity")).multiply(price));total=total.add(amount);lines.add(row("request_item_id",requestItem,"unit_price",price,"amount",amount));}
  check(seen.size()==required.size(),"报价必须覆盖申请全部材料");long quote=db.insert("quotes",row("request_id",requestId,"supplier_id",supplier,"delivery_days",days,"valid_until",valid,"note",optional(input,"note"),"total_amount",total));for(Map<String,Object> l:lines){l.put("quote_id",quote);db.insert("quote_items",l);}auth.audit("RECORD_QUOTE","quote",quote,"供应商 "+s.get("name")+" 总额 "+total);return quotes(requestId).stream().filter(x->((Number)x.get("id")).longValue()==quote).findFirst().orElseThrow();
 }
 @Transactional public Map<String,Object> award(long requestId,Map<String,Object> input){auth.require("order:write");Map<String,Object> r=request(requestId,true);check("APPROVED".equals(r.get("status")),"未审批通过不可生成采购订单");check(db.list("SELECT id FROM purchase_orders WHERE request_id=?",requestId).isEmpty(),"此申请已生成订单，禁止重复超量采购");long quoteId=id(input,"quote_id");String reason=text(input,"reason");Map<String,Object> q=db.one("SELECT * FROM quotes WHERE id=? AND request_id=? AND tenant_id=1",quoteId,requestId);check(!LocalDate.parse(q.get("valid_until").toString()).isBefore(LocalDate.now()),"报价已过期，请重新询价");Map<String,Object> s=db.one("SELECT * FROM suppliers WHERE id=? AND tenant_id=1",q.get("supplier_id"));check("ACTIVE".equals(s.get("status")),"供应商已停用");if(s.get("qualification_expiry")!=null)check(!LocalDate.parse(s.get("qualification_expiry").toString()).isBefore(LocalDate.now()),"供应商资质已过期");
  long order=db.insert("purchase_orders",row("code",code("PO"),"project_id",r.get("project_id"),"request_id",requestId,"quote_id",quoteId,"supplier_id",q.get("supplier_id"),"total_amount",q.get("total_amount"),"status","OPEN","buyer_id",auth.id()));
  for(Map<String,Object> l:db.list("SELECT ri.*,qi.unit_price quoted_price,qi.amount quoted_amount FROM request_items ri JOIN quote_items qi ON qi.request_item_id=ri.id WHERE qi.quote_id=?",quoteId))db.insert("order_items",row("order_id",order,"material_id",l.get("material_id"),"request_item_id",l.get("id"),"quantity",l.get("quantity"),"unit_price",l.get("quoted_price"),"amount",l.get("quoted_amount")));
  db.update("quotes",quoteId,row("selected",true,"selection_reason",reason));db.insert("payables",row("order_id",order,"supplier_id",q.get("supplier_id"),"project_id",r.get("project_id"),"amount",BigDecimal.ZERO,"paid_amount",BigDecimal.ZERO));auth.audit("AWARD_ORDER","purchase_order",order,reason);return orderDetail(order);
 }
 public List<Map<String,Object>> orders(){auth.require("order:read");return db.list("SELECT o.*,p.name project_name,s.name supplier_name,u.name buyer_name FROM purchase_orders o JOIN projects p ON p.id=o.project_id JOIN suppliers s ON s.id=o.supplier_id JOIN users u ON u.id=o.buyer_id WHERE "+auth.projectFilter("p")+" ORDER BY o.id DESC");}
 public Map<String,Object> orderDetail(long id){auth.require("order:read");Map<String,Object> o=order(id,false);o.putAll(db.one("SELECT p.name project_name,s.name supplier_name,s.contact,s.phone,q.selection_reason,q.delivery_days,r.code request_code,u.name buyer_name FROM purchase_orders o JOIN projects p ON p.id=o.project_id JOIN suppliers s ON s.id=o.supplier_id JOIN quotes q ON q.id=o.quote_id JOIN purchase_requests r ON r.id=o.request_id JOIN users u ON u.id=o.buyer_id WHERE o.id=?",id));o.put("items",db.list("SELECT i.*,m.name material_name,m.specification,m.unit FROM order_items i JOIN materials m ON m.id=i.material_id WHERE i.order_id=? ORDER BY i.id",id));o.put("receipts",db.list("SELECT r.*,w.name warehouse_name,u.name operator_name FROM receipts r JOIN warehouses w ON w.id=r.warehouse_id JOIN users u ON u.id=r.operator_id WHERE r.order_id=? ORDER BY r.id DESC",id));o.put("payments",db.list("SELECT t.*,u.name operator_name FROM payments t JOIN payables p ON p.id=t.payable_id JOIN users u ON u.id=t.operator_id WHERE p.order_id=? ORDER BY t.id DESC",id));return o;}
 @Transactional public Map<String,Object> cancel(long id,Map<String,Object> input){auth.require("order:write");Map<String,Object> o=order(id,true);check("OPEN".equals(o.get("status")),"只有未收货订单可取消");check(db.list("SELECT id FROM receipts WHERE order_id=?",id).isEmpty(),"有收货记录不可取消");db.update("purchase_orders",id,row("status","CANCELLED"));auth.audit("CANCEL_ORDER","purchase_order",id,text(input,"reason"));return orderDetail(id);}
 public List<Map<String,Object>> pending(){auth.require("request:approve");return db.list("SELECT r.*,p.name project_name,u.name applicant_name FROM purchase_requests r JOIN projects p ON p.id=r.project_id JOIN users u ON u.id=r.applicant_id WHERE r.status='PENDING' AND "+auth.projectFilter("p")+" ORDER BY r.id");}
 public List<Map<String,Object>> approvals(){auth.require("request:read");return db.list("SELECT a.*,r.code request_code,p.name project_name,u.name operator_name FROM approvals a JOIN purchase_requests r ON r.id=a.request_id JOIN projects p ON p.id=r.project_id JOIN users u ON u.id=a.operator_id WHERE "+auth.projectFilter("p")+" ORDER BY a.id DESC");}
}
